import { randomUUID } from "node:crypto";
import { and, asc, eq, gt } from "drizzle-orm";
import { Hono } from "hono";
import { z } from "zod";
import { db } from "../db/client.ts";
import { notes } from "../db/schema.ts";
import { requireRole, type AppEnv } from "../lib/auth.ts";
import { cursorQuery, decodeCursor, page, paginate } from "../lib/cursor.ts";
import { idempotency } from "../lib/idempotency.ts";
import { ProblemError } from "../lib/problem.ts";
import { respond, validate } from "../lib/validate.ts";

const Note = z.object({ id: z.string(), title: z.string(), body: z.string().nullable() });
const NoteCreate = z.object({ title: z.string().min(1).max(200), body: z.string().optional() });
const IdParam = z.object({ id: z.string().min(1) });
const Empty = z.object({});

const toNote = (r: Pick<typeof notes.$inferSelect, "id" | "title" | "body">): z.infer<typeof Note> => ({
  id: r.id,
  title: r.title,
  body: r.body,
});

export const notesRouter = new Hono<AppEnv>();

notesRouter.get("/", requireRole("owner", "member", "viewer"), validate("query", cursorQuery), (c) => {
  const { cursor, limit } = c.req.valid("query");
  const after = decodeCursor(cursor);
  const rows = db
    .select({ id: notes.id, title: notes.title, body: notes.body })
    .from(notes)
    .where(and(eq(notes.workspaceId, c.get("user").workspaceId), after ? gt(notes.id, after) : undefined))
    .orderBy(asc(notes.id))
    .limit(limit + 1)
    .all();
  const result = paginate(rows, limit);
  return respond(c, page(Note), { data: result.data.map(toNote), next_cursor: result.next_cursor });
});

notesRouter.post("/", requireRole("owner", "member"), idempotency(), validate("json", NoteCreate), (c) => {
  const key = c.req.header("Idempotency-Key");
  if (!key) throw new ProblemError(422, "Validation failed", "Idempotency-Key header is required");
  const { title, body } = c.req.valid("json");
  const existing = db
    .select({ id: notes.id })
    .from(notes)
    .where(and(eq(notes.workspaceId, c.get("user").workspaceId), eq(notes.title, title)))
    .get();
  if (existing) throw new ProblemError(409, "Conflict", "A note with this title already exists in this workspace");
  const row = db
    .insert(notes)
    .values({ id: randomUUID(), workspaceId: c.get("user").workspaceId, title, body: body ?? null })
    .returning({ id: notes.id, title: notes.title, body: notes.body })
    .get();
  return respond(c, Note, toNote(row), 201);
});

notesRouter.get("/:id", requireRole("owner", "member", "viewer"), validate("param", IdParam), (c) => {
  const { id } = c.req.valid("param");
  const row = db
    .select({ id: notes.id, title: notes.title, body: notes.body })
    .from(notes)
    .where(and(eq(notes.workspaceId, c.get("user").workspaceId), eq(notes.id, id)))
    .get();
  if (!row) throw new ProblemError(404, "Not Found", "Note not found");
  return respond(c, Note, toNote(row));
});

notesRouter.delete("/:id", requireRole("owner"), validate("param", IdParam), (c) => {
  const { id } = c.req.valid("param");
  const row = db
    .select({ id: notes.id })
    .from(notes)
    .where(and(eq(notes.workspaceId, c.get("user").workspaceId), eq(notes.id, id)))
    .get();
  if (!row) throw new ProblemError(404, "Not Found", "Note not found");
  db.delete(notes).where(and(eq(notes.workspaceId, c.get("user").workspaceId), eq(notes.id, id))).run();
  return respond(c, Empty, {}, 204);
});

import { describe, expect, it } from "vitest";
import { as } from "./helpers.ts";

type Note = { id: string; title: string; body: string | null };
type Page = { data: Note[]; next_cursor: string | null };

describe("/v1/notes", () => {
  it("creates, lists, gets, and deletes notes scoped to workspace", async () => {
    const member = as("notes1", "member");
    const created = await member("POST", "/v1/notes", { title: "a", body: "body" }, { "Idempotency-Key": "n1" });
    expect(created.status).toBe(201);
    const note = (await created.json()) as Note;
    expect(note).toMatchObject({ title: "a", body: "body" });

    const listed = (await (await member("GET", "/v1/notes?limit=1")).json()) as Page;
    expect(listed.data).toEqual([note]);
    expect((await (await as("notes2", "viewer")("GET", "/v1/notes")).json() as Page).data).toEqual([]);
    expect(await (await member("GET", `/v1/notes/${note.id}`)).json()).toEqual(note);

    expect((await member("DELETE", `/v1/notes/${note.id}`)).status).toBe(403);
    expect((await as("notes1", "owner")("DELETE", `/v1/notes/${note.id}`)).status).toBe(204);
    expect((await member("GET", `/v1/notes/${note.id}`)).status).toBe(404);
  });

  it("enforces title uniqueness, roles, validation, and Idempotency-Key", async () => {
    const member = as("notes3", "member");
    expect((await as("notes3", "viewer")("POST", "/v1/notes", { title: "x" }, { "Idempotency-Key": "v" })).status).toBe(403);
    expect((await member("POST", "/v1/notes", { title: "" }, { "Idempotency-Key": "bad" })).status).toBe(422);
    expect((await member("POST", "/v1/notes", { title: "x" })).status).toBe(422);
    expect((await member("POST", "/v1/notes", { title: "x" }, { "Idempotency-Key": "x1" })).status).toBe(201);
    expect((await member("POST", "/v1/notes", { title: "x" }, { "Idempotency-Key": "x2" })).status).toBe(409);
  });
});

